      return;
    }

    const question = questions[current];
    let answered = false;
    const options = element("div", "play-options");
    const feedback = element("div", "preview-feedback");
    feedback.setAttribute("aria-live", "polite");
    feedback.setAttribute("aria-atomic", "true");
    const navigation = element("div", "buttons preview-navigation");

    question.options.forEach((option, index) => {
      const button = element("button", "play-option");
      button.type = "button";
      button.setAttribute("aria-label", option.text);
      const badge = element("span", "play-option__letter", letter(index));
      badge.setAttribute("aria-hidden", "true");
      button.append(badge, element("span", "play-option__title", option.text));
