      if @quiz.update(quiz_params)
        redirect_to moderate_quiz_path(@quiz), status: :see_other
      else
        render :edit, status: :unprocessable_entity
      end
    end

    def destroy
      @quiz.with_lock { @quiz.destroy! }
      redirect_to moderate_root_path, status: :see_other
    end

    def export
      @quiz_json = QuizTransfer.export(@quiz)
    end

    def import
      @quiz_json = ""
    end

    def create_import
      @quiz_json = params[:quiz_json].is_a?(String) ? params[:quiz_json] : ""
      quiz = QuizTransfer.import(@quiz_json)
      redirect_to moderate_quiz_path(quiz), status: :see_other
    rescue QuizTransfer::InvalidData => error
      @import_error = error.message
      render :import, status: :unprocessable_entity
    end

    def preview
      @preview_questions = @quiz.questions.where(active: true).map do |question|
        { text: question.text, options: question.options }
      end
      render layout: "preview"
    end

    private

    def set_quiz
      @quiz = Quiz.find(params[:id])
    end

